create or replace function public.is_board_member(p_board_id bigint, p_user_id uuid, p_role text)
returns boolean
language sql stable
as $$
  select case
    when exists (
      select 1 from public.board_members bm
      where bm.board_id = p_board_id
        and bm.user_id = p_user_id
        and bm.role = p_role
    ) then true
    else false
  end;
$$;

