revoke all on public.boards from anon, authenticated;
revoke all on public.board_members from anon, authenticated;
revoke all on public.cards from anon, authenticated;
-- authenticated users get implicit select on their own data via policies, but no direct grants on rows.
-- We revoke direct table access grants for authenticated to ensure they ONLY use policies.
revoke select, insert, update, delete on public.boards from authenticated;
revoke select, insert, update, delete on public.board_members from authenticated;
revoke select, insert, update, delete on public.cards from authenticated;
