-- Enable RLS on both tables
alter table public.friendships enable row level security;
alter table public.posts enable row level security;

-- Helper function to check if two users are friends (bidirectional accepted)
create or replace function public.is_friends(user_a uuid, user_b uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1 from public.friendships
    where (requester_id = user_a and addressee_id = user_b and status = 'accepted')
    or (requester_id = user_b and addressee_id = user_a and status = 'accepted')
  );
$$;

-- Policy R1: Read Posts
create policy "Users can read posts based on audience and friendship"
on public.posts
for select
using (
  audience = 'public'
  or audience = 'friends' and public.is_friends(auth.uid(), author_id)
