-- Enable RLS on all tables
alter table public.org_admins enable row level security;
alter table public.files enable row level security;

-- Function to check if user is an org admin
create or replace function public.is_org_admin(user_uuid uuid)
returns boolean
language sql
stable
security definer
as $$
  select exists (select 1 from public.org_admins where user_id = user_uuid);
$$;

-- Policy R1: Users see their own files; Org admins see all files
create policy "Users view own files, org admins view all"
  on public.files
  for select
  using (
    auth.uid() = owner_id
    or public.is_org_admin(auth.uid())
  );

-- Policy R2 & R3 & R4: Insert, Update (rename), Delete logic
-- Insert: Users upload as themselves; Org admins can upload
create policy "Users upload files, org admins can upload"
  on public.files
  for insert
  with check (
    auth.uid() = owner_id
    or public.is_org_admin(auth.uid())
  );

-- Update: Users update own files; Org admins update any; Legal hold blocks rename/delete
create policy "Users update own files, org admins update any, legal hold blocks"
  on public.files
  for update
  using (
    (auth.uid() = owner_id and not legal_hold)
    or (public.is_org_admin(auth.uid()) and not legal_hold)
  );

-- Delete: Users delete own files; Org admins delete any; Legal hold blocks
create policy "Users delete own files, org admins delete any, legal hold blocks"
  on public.files
  for delete
  using (
    (auth.uid() = owner_id and not legal_hold)
    or (public.is_org_admin(auth.uid()) and not legal_hold)
  );

-- Policy R5: Nobody changes org_admins through the app
create policy "Prevent changes to org_admins"
  on public.org_admins
  for all
  with check (false);

-- Policy R6: Anonymous users cannot do anything
-- (Implicitly handled by requiring auth.uid() in policies, but explicit deny for clarity if needed)
-- Since all policies require auth.uid() to match, anonymous users are blocked by default.

-- Policy R7: Service role has full access (handled by bypassing RLS, but explicit grant for clarity)
grant all on all tables in schema public to service_role;
grant all on all functions in schema public to service_role;
grant all on all sequences in schema public to service_role;

-- Ensure anonymous users have no access (explicit revoke just in case)
revoke all on public.files from anon;
revoke all on public.org_admins from anon;
revoke all on all tables in schema public from anon;
revoke all on all functions in schema public from anon;
revoke all on all sequences in schema public from anon;
