-- Enable RLS on all tables
alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.org_documents enable row level security;

-- Helper function to check if user has SSO session
create or replace function public.check_sso()
returns boolean
security definer
set search_path = public
language sql
as $$
  select case
    when auth.jwt() is not null
      and array_join(auth.jwt().amr, ',') like '%sso/saml%'
    then true
    else false
  end;
$$;

-- Helper function to check if user is a member of the target org
create or replace function public.is_org_member(org_id bigint)
returns boolean
security definer
set search_path = public
language sql
as $$
  select exists (
    select 1 from public.org_members
    where org_members.org_id = org_id
    and org_members.user_id = auth.uid()
  );
$$;

-- Helper function to check if user is an admin of the target org
create or replace function public.is_org_admin(org_id bigint)
returns boolean
security definer
set search_path = public
language sql
as $$
  select exists (
    select 1 from public.org_members
    where org_members.org_id = org_id
    and org_members.user_id = auth.uid()
    and org_members.role = 'admin'
  );
$$;

-- Helper function to get the org_id for the current user's first org (for read access)
create or replace function public.get_user_org_id()
returns bigint
security definer
set search_path = public
language sql
as $$
  select org_id from public.org_members
  where user_id = auth.uid()
  limit 1;
$$;

-- Helper function to check if user is in the specific org being accessed
create or replace function public.is_in_org(org_id bigint)
returns boolean
security definer
set search_path = public
language sql
as $$
  select exists (
    select 1 from public.org_members
    where org_members.org_id = org_id
    and org_members.user_id = auth.uid()
  );
$$;

-- Policy for orgs (R1, R3)
create policy "Users can see their own orgs" on public.orgs
for select
using (
  auth.uid()::text in (
    select user_id from public.org_members where org_id = id
  )
) with check (true);

-- Policy for org_members (R1, R4)
create policy "Users can see their own org memberships" on public.org_members
for select
using (user_id = auth.uid());

-- Policy for org_documents (R1, R2)
create policy "Users can see documents of orgs they are members of" on public.org_documents
for select
using (
  org_id in (
    select org_id from public.org_members where user_id = auth.uid()
  )
);

create policy "Admins can create documents with SSO" on public.org_documents
for insert
with check (
  is_org_admin(org_id) and check_sso()
);

create policy "Admins can update documents with SSO" on public.org_documents
for update
using (
  org_id in (
    select org_id from public.org_members where user_id = auth.uid() and role = 'admin'
  ) and check_sso()
);

create policy "Admins can delete documents with SSO" on public.org_documents
for delete
using (
  org_id in (
    select org_id from public.org_members where user_id = auth.uid() and role = 'admin'
  ) and check_sso()
);

-- Grants for service_role (R6)
grant all on all tables in schema public to service_role;
grant all on all functions in schema public to service_role;

-- Ensure anonymous users cannot do anything (R5)
-- (Implicitly handled by RLS since no policy allows anon to select/insert/update/delete)
revoke all on public.orgs from anon;
revoke all on public.org_members from anon;
revoke all on public.org_documents from anon;

-- Explicitly deny anon on functions if needed (though security definer handles it)
revoke all on function public.check_sso() from anon;
revoke all on function public.is_org_member() from anon;
revoke all on function public.is_org_admin() from anon;
revoke all on function public.get_user_org_id() from anon;
revoke all on function public.is_in_org() from anon;
