create or replace function public.is_set_owner(set_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.is_workout_owner(w.id)
  from public.workout_sets s
  join public.workouts w on w.id = s.workout_id
  where s.id = set_id;
$$;

