  for all using (auth.jwt() is not null);
create policy "Deny anonymous access to all tables" on public.support_agents
  for all using (auth.jwt() is not null);
create policy "Deny anonymous access to all tables" on public.supervisors
  for all using (auth.jwt() is not null);

-- R4: Users can see their own support_agents and supervisors rows
create policy "Users see own support_agents" on public.support_agents
  for select using (auth.uid() = user_id);
create policy "Users see own supervisors" on public.supervisors
  for select using (auth.uid() = user_id);

-- R4: Nobody can change customers, agents or supervisors through the app
create policy "Deny insert/update/delete on customers" on public.customers
  for all using (false);
create policy "Deny insert/update/delete on support_agents" on public.support_agents
  for all using (false);
create policy "Deny insert/update/delete on supervisors" on public.supervisors
  for all using (false);

-- R1 & R6: Supervisors can read full customers; Service role bypasses RLS
create policy "Supervisors read full customers" on public.customers
  for select using (
    auth.jwt() is not null 
    and auth.jwt()->>'role' = 'service_role'
    or auth.jwt() is not null 
    and exists (
      select 1 from public.supervisors 
      where supervisors.user_id = auth.uid()
    )
  );

-- R2: Create view for masked data
create or replace view public.support_customers as
select 
  id,
  region,
  full_name,
  substring(email from 1 || '***' || substring(email from '@')) as email_masked,
  '******' || substring(phone from length(phone) - 3) as phone_masked
from public.customers;

-- R3: Support agents see only their region; others see nothing
create policy "Support agents see regional customers" on public.support_customers
  for select using (
    auth.jwt() is not null 
    and exists (
      select 1 from public.support_agents 
      where support_agents.user_id = auth.uid()
      and support_agents.region = support_customers.region
    )
  );

-- R6: Grant service role full access to the view for server-side code
grant all on public.support_customers to service_role;
