```sql
-- Enable RLS on all tables
alter table public.customers enable row level security;
alter table public.support_agents enable row level security;
alter table public.supervisors enable row level security;

-- Helper function to create the view later
create or replace function create_support_customers_view()
returns void as $$
begin
  drop view if exists public.support_customers cascade;
  create view public.support_customers as
  select 
    c.id,
    c.region,
    c.full_name,
    substr(c.email, 1, 1) || '***' || split_part(c.email, '@', 2) || '@' || split_part(c.email, '@', 2) || split_part(c.email, '@', 2) as email_masked, -- Note: The prompt had a typo "asha@example.com becomes a***@example.com". Logic: char + *** + rest.
    '******' || substr(c.phone, length(c.phone) - 3) as phone_masked
  from public.customers c;
end;
$$ language plpgsql security definer;

-- Helper function to mask email correctly (fixing the logic in the view creation step)
create or replace function mask_email(email text)
returns text as $$
begin
  return substr(email, 1, 1) || '***' || substr(email, string_position(email, '@') + 1);
end;
$$ language plpgsql stable;

-- Helper function to mask phone correctly
create or replace function mask_phone(phone text)
returns text as $$
begin
  return '******' || substr(phone, length(phone) - 3);
end;
$$ language plpgsql stable;

-- Re-define the view with correct masking logic and security definer
create or replace view public.support_customers as
  select 
    c.id,
    c.region,
    c.full_name,
    mask_email(c.email) as email_masked,
    mask_phone(c.phone) as phone_masked
  from public.customers c;

-- Policy R5: Anonymous visitors cannot see anything
-- Explicitly deny anon access to support_customers, customers, support_agents, supervisors
create policy "Deny anonymous access to customers" on public.customers for select using (false);
create policy "Deny anonymous access to support_customers" on public.support_customers for select using (false);
create policy "Deny anonymous access to support_agents" on public.support_agents for select using (false);
create policy "Deny anonymous access to supervisors" on public.supervisors for select using (false);

-- Policy R4: Users can see their own support_agents and supervisors rows
create policy "Agents see own records" on public.support_agents for select using (auth.uid() = user_id);
create policy "Supervisors see own records" on public.supervisors for select using (auth.uid() = user_id);

-- Policy R4: Nobody can change customers, agents or supervisors through the app (Deny Insert/Update/Delete for anon/authenticated)
-- Explicitly deny modifications for authenticated users to these tables
create policy "Deny modify customers" on public.customers for all using (false) with check (false);
create policy "Deny modify support_agents" on public.support_agents for all using (false) with check (false);
create policy "Deny modify supervisors" on public.supervisors for all using (false) with check (false);

-- Policy R1: Supervisors can read the full customers table
create policy "Supervisors read all customers" on public.customers for select using (
  exists (select 1 from public.supervisors s where s.user_id = auth.uid())
);

-- Policy R3 & R6: Support agent sees only their region; Server-side (service_role) sees all
-- Note: RLS policies cannot directly check 'service_role'. We rely on the fact that service_role bypasses RLS.
-- However, to ensure authenticated non-superusers/authenticated users (who are not supervisors) cannot see support_customers or customers, we rely on the Deny policies above.
-- For support_customers, we need a policy that allows authenticated users IF they are agents in that region.
-- Since RLS bypasses for service_role, we only define policies for 'authenticated' role here.
create policy "Support agents see regional customers" on public.support_customers for select using (
  auth.jwt()->>'role' != 'service_role' -- Ensure not service role (handled by default allow if policy exists for role)
  AND auth.uid() = (
    select user_id from public.support_agents 
    where region = (select region from public.support_customers where id = public.support_customers.id)
    limit 1
  )
);

-- Correction for R3/R6 logic with standard RLS syntax (checking auth.uid against the view's data source logic via a join or subquery is hard in SELECT USING)
-- Better approach for R3: Allow authenticated users to read support_customers ONLY if their user_id matches an agent in the region of the row.
-- Since we cannot easily join in the USING clause of a view policy, let's create a policy on the underlying 'customers' table for agents too? 
-- The requirement says: "Support agents look customers up with ... support_customers".
-- So we need RLS on the VIEW `public.support_customers`.
-- RLS on views: We can use a JOIN in the USING clause? No.
-- Standard way: Create a policy that checks if the user is an agent in the same region as the row.
-- We can do this by exposing the region of the agent and the row, but we can't reference the row's region in the policy condition directly without a join.
-- Workaround: The view `support_customers` has `region`. We can't easily filter by `region = (select ... from support_agents where user_id = auth.uid())` inside the policy's `using` clause unless we use a CTE or subquery logic that supports it.
-- PostgreSQL allows subqueries in policy conditions.
create policy "Agents read regional customers view" on public.support_customers for select using (
  auth.jwt()->>'role' != 'service_role'
  AND (
    select user_id from public.support_agents where user_id = auth.uid() and region = region
  ) is not null
);

-- Final check for R6: Service role bypasses RLS, so it sees everything on the view.
-- R4 update: Users can edit their own user_metadata. This is handled by Supabase Auth hooks or direct auth.update, not via RLS on these tables.
-- The prompt asks for RLS.

-- Grant service_role full access explicitly if needed (usually default for service_role), but ensuring they can see the view.
-- RLS bypass for service_role means they don't need explicit policies, but we ensure the view exists.
-- No grants needed as service_role bypasses RLS.

-- Ensure authenticated users cannot insert/delete/update on support_customers (it's a view, so this is inherited from customers, but we lock the view itself too)
create policy "Deny modify support_customers view" on public.support_customers for all using (false) with check (false);
