create or replace function public.is_user_highest_bidder(user_id uuid, auction_id bigint)
returns boolean
language sql
stable
as $$
  select b.bidder_id = $1
  from public.bids b
  where b.auction_id = $2 and b.amount = (select highest_bid from public.auctions where id = $2);
$$;

-- Helper function to check if bid amount is valid
