as $$
declare
  v_starting_price numeric;
  v_highest_bid numeric;
  v_min_increment numeric;
begin
  select starting_price, highest_bid, min_increment
  into v_starting_price, v_highest_bid, v_min_increment
  from public.auctions
  where id = auction_id;

  if v_highest_bid is null then
    return amount >= v_starting_price;
  else
    return amount > v_highest_bid + v_min_increment;
  end if;
end;
