on public.bids
for select
using ( exists ( select 1 from public.auctions where auctions.id = bids.auction_id and auctions.seller_id = auth.uid() ) );

-- Policy R2: Nobody can create, change or delete auctions or bids directly
-- (Create and Update policies are omitted, Delete policies are omitted)
-- Only select policies are active, preventing direct modifications via app logic that bypasses RPC

-- Function to place a bid
create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_auction public.auctions;
  v_new_high_bid numeric;
  v_min_increment numeric;
begin
  -- Check if user is signed in
  if auth.role() = 'anon' then
    raise exception 'Must be signed in to place a bid';
  end if;

  -- Check if auction exists
  select * into v_auction
  from public.auctions
  where id = p_auction_id;

  if not found then
    raise exception 'Auction not found';
  end if;

  -- Check if auction has ended
  if now() > v_auction.ends_at then
    raise exception 'Auction has ended';
  end if;

  -- Check if caller is the seller
  if v_auction.seller_id = auth.uid() then
    raise exception 'Sellers cannot bid on their own auctions';
  end if;

  -- Check minimum increment logic
  if p_amount <= v_auction.starting_price then
    if v_auction.highest_bid is null then
       raise exception 'Bid must be above starting price';
    end if;
  end if;

  -- Determine new highest bid
  if v_auction.highest_bid is null then
    v_new_high_bid := p_amount;
  else
    v_min_increment := v_auction.min_increment;
    if p_amount <= v_auction.highest_bid + v_min_increment then
      raise exception 'Bid amount is too low';
    else
      v_new_high_bid := p_amount;
    end if;
  end if;

  -- Insert the bid
  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, auth.uid(), p_amount)
  returning id;

  -- Update the auction's highest bid
  update public.auctions
  set highest_bid = v_new_high_bid
  where id = p_auction_id;

  return v_new_high_bid;
end;
$$;

-- Grant service_role full access to bypass RLS for backend operations
grant all on public.auctions to service_role;
grant all on public.bids to service_role;
grant execute on function public.place_bid(bigint, numeric) to service_role;

-- Revoke public access explicitly if any (though RLS handles it, this ensures no implicit grants)
revoke all on public.auctions from anon, authenticated;
revoke all on public.bids from anon, authenticated;
revoke all on function public.place_bid from anon, authenticated;
