-- Enable RLS on tables
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

-- Helper function to get current auction details for policy evaluation
create or replace function public.get_auction_context()
returns table (
  auction_id bigint,
  ends_at timestamptz,
  highest_bid numeric,
  min_increment numeric
) language plpgsql security definer
as $$
begin
  return query select 
    a.id as auction_id,
    a.ends_at,
    a.highest_bid,
    a.min_increment
  from auctions a
  where a.id = current_setting('app.current_auction_id')::bigint;
end;
$$;

-- Helper function to update auction state after a bid
create or replace function public.update_auction_state(new_bid_amount numeric)
returns trigger
language plpgsql security definer
as $$
begin
  update auctions
  set highest_bid = new_bid_amount
  where id = coalesce(current_setting('app.current_auction_id')::bigint, new.auction_id);
  return new;
end;
$$;

-- Policy for Auctions: Read access
create policy "Users can read auctions" on public.auctions
  for select
  using (true);

-- Policy for Bids: Read access
create policy "Users can read own bids and sellers can read all bids" on public.bids
  for select
  using (
    auth.jwt()->>'role' = 'seller' 
    OR (auth.uid() = bidder_id)
  );

-- Function to handle bid placement logic
create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
as $$
declare
  v_auction_id bigint;
  v_seller_id uuid;
  v_ends_at timestamptz;
  v_highest_bid numeric;
  v_min_increment numeric;
  v_new_high numeric;
  v_error text;
begin
  -- Set context for helper function
  execute 'set app.current_auction_id = ' || quote_literal(p_auction_id);

  -- Get auction details
  select id, seller_id, ends_at, highest_bid, min_increment
  into v_auction_id, v_seller_id, v_ends_at, v_highest_bid, v_min_increment
  from auctions
  where id = p_auction_id;

  if not found then
    raise exception 'Auction not found';
  end if;

  -- Check if auction has ended
  if v_ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  -- Check if caller is seller
  if auth.uid() = v_seller_id then
    raise exception 'Sellers cannot place bids';
  end if;

  -- Check authentication
  if not auth.jwt() then
    raise exception 'User must be signed in to place a bid';
  end if;

  -- Validate bid amount
  if v_highest_bid is null then
    -- First bid: must be >= starting price
    if p_amount < coalesce(v_highest_bid, 0) then
      -- Assuming starting_price is the baseline for first bid
      if p_amount < (select starting_price from auctions where id = p_auction_id) then
        raise exception 'Bid amount must be at least the starting price';
      end if;
    else
      if p_amount <= v_highest_bid then
        raise exception 'Bid amount must be greater than current highest bid';
      end if;
    end if;
  else
    -- Subsequent bids: must be > highest + min_increment
    v_new_high := v_highest_bid + v_min_increment;
    if p_amount <= v_new_high then
      raise exception 'Bid amount must be at least $1 higher than current highest bid plus minimum increment';
    end if;
  end if;

  -- Insert the bid
  insert into bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now());

  -- Get the new highest bid value (which is the inserted amount)
  v_new_high := p_amount;

  -- Update the auction's highest bid (handled by trigger or manual update here)
  -- Since we are in a function, we'll do it manually to ensure consistency
  update auctions
  set highest_bid = v_new_high
  where id = p_auction_id;

  return v_new_high;
exception
  when others then
    rollback;
    raise;
end;
$$;

-- Trigger to ensure auction state is updated if direct insertion happens (backup)
create trigger trigger_update_auction_state
after insert on public.bids
for each row
execute function public.update_auction_state(new.amount);

-- Grant service role full access
grant all on all tables in schema public to service_role;
grant all on all functions in schema public to service_role;
